    mul.wide.u32 offA, idx32, 4;
    add.u64 offA, baseSA, offA;
    st.shared.f32 [offA], a;

    mul.wide.u32 offB, idx32, 4;
    add.u64 offB, baseSB, offB;
    st.shared.f32 [offB], b;

    // Synchronize before compute
    bar.sync 0;

    // Compute accumulation over the tile
    mov.u32 rk, 0;
